    if not isinstance(text, str) or len(text) != 9:
        raise ValueError("Text must be exactly nine characters")

    valid_chars = set('rwx-STMt')
    if not all(c in valid_chars for c in text):
        raise ValueError("Invalid character in text")

    mode = 0

    # Owner part
    o_read, o_write, o_execute = text[0], text[1], text[2]
    set_user = False
    if o_execute == 's':
        set_user = True
        mode |= 0o4000
        if o_read == 'r' and o_write == '-':
            mode |= 0o400 | 0o100
        else:
            raise ValueError("Invalid owner execute 's' with wrong read/write")
    elif o_execute == 'S':
