        if o_read == 'r' and o_write == '-':
            mode |= 0o400
        else:
            raise ValueError("Invalid owner execute 'S' with wrong read/write")
    else:
        if o_execute not in ('x', '-'):
            raise ValueError(f"Invalid owner execute character '{o_execute}'")
        if o_read == 'r':
            mode |= 0o400
        if o_write == 'w':
            mode |= 0o200
        if o_execute == 'x':
            mode |= 0o100

    # Group part
