    set_group = False
    if g_execute == 's':
        set_group = True
        mode |= 0o2000
        if g_read == 'r' and g_write == '-':
            mode |= 0o040 | 0o010
        else:
            raise ValueError("Invalid group execute 's' with wrong read/write")
    elif g_execute == 'S':
        set_group = True
        mode |= 0o2000
        if g_read == 'r' and g_write == '-':
            mode |= 0o040
        else:
            raise ValueError("Invalid group execute 'S' with wrong read/write")
    else:
        if g_execute not in ('x', '-'):
            raise ValueError(f"Invalid group execute character '{g_execute}'")
        if g_read == 'r':
            mode |= 0o040
        if g_write == 'w':
            mode |= 0o020
        if g_execute == 'x':
            mode |= 0o010

    # Others part
    oth_read, oth_write, oth_execute = text[6], text[7], text[8]
    if oth_execute == 't':
        mode |= 0o1000
        if oth_read == 'r' and oth_write == '-':
            mode |= 0o004 | 0o001
        else:
            raise ValueError("Invalid others execute 't' with wrong read/write")
    elif oth_execute == 'T':
