def mode_to_text(mode):
    if not isinstance(mode, int):
        raise ValueError("mode must be an integer")
    if mode < 0 or mode > 0o7777:
        raise ValueError("mode must be between 0 and 0o7777")

    # Extract special bits
    set_user = (mode & 0o4000) != 0
    set_group = (mode & 0o2000) != 0
    sticky = (mode & 0o1000) != 0

    # Owner permissions
    owner_r = (mode & 0o400) != 0
    owner_w = (mode & 0o200) != 0
    owner_x = (mode & 0o100) != 0

    # Group permissions
    group_r = (mode & 0o040) != 0
    group_w = (mode & 0o020) != 0
    group_x = (mode & 0o010) != 0

    # Others permissions
    others_r = (mode & 0o004) != 0
    others_w = (mode & 0o002) != 0
    others_x = (mode & 0o001) != 0

    def get_triple(r, w, x, special, is_owner_or_group):
        r_char = 'r' if r else '-'
        w_char = 'w' if w else '-'
        if special:
            if x:
                s_or_t = 's' if is_owner_or_group else 't'
            else:
                s_or_t = 'S' if is_owner_or_group else 'T'
            return f"{r_char}{w_char}{s_or_t}"
        else:
            x_char = 'x' if x else '-'
            return f"{r_char}{w_char}{x_char}"

    owner_triple = get_triple(owner_r, owner_w, owner_x, set_user, True)
    group_triple = get_triple(group_r, group_w, group_x, set_group, True)
    others_triple = get_triple(others_r, others_w, others_x, sticky, False)

    return owner_triple + group_triple + others_triple

