def expand_tabs(line, width):
    if not isinstance(line, str):
        raise ValueError("line must be a string")
    if '\n' in line or '\r' in line:
        raise ValueError("line contains invalid characters")
    if not isinstance(width, int):
        raise ValueError("width must be an integer")
    if width < 1 or width > 32:
        raise ValueError("width must be between 1 and 32")

    result = []
    current_pos = 0
    for c in line:
        if c == '\t':
            next_tab = ((current_pos // width) + 1) * width
            spaces_needed = next_tab - current_pos
            result.append(' ' * spaces_needed)
            current_pos = next_tab
        else:
            result.append(c)
            current_pos += 1
    return ''.join(result)

def collapse_spaces(line, width):
    if not isinstance(line, str):
        raise ValueError("line must be a string")
    if '\n' in line or '\r' in line or '\t' in line:
        raise ValueError("line contains invalid characters")
    if not isinstance(width, int):
        raise ValueError("width must be an integer")
    if width < 1 or width > 32:
        raise ValueError("width must be between 1 and 32")

    chunks = [line[i:i+width] for i in range(0, len(line), width)]
    processed = []
    for chunk in chunks:
        if len(chunk) == width:
            trailing = 0
            for c in reversed(chunk):
                if c == ' ':
                    trailing += 1
                else:
                    break
            if trailing >= 2:
                new_chunk = chunk[:-trailing] + '\t'
                processed.append(new_chunk)
            else:
                processed.append(chunk)
        else:
            processed.append(chunk)
    return ''.join(processed)

