def qp_encode(data):
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError("Data must be bytes or bytearray")

    tokens = []
    for i, byte in enumerate(data):
        if byte == 32:
            if i == len(data) - 1:
                tokens.append('=20')
            else:
                tokens.append(' ')
        elif 33 <= byte <= 126 and byte != 61:
            tokens.append(chr(byte))
        else:
            tokens.append(f'={byte:02X}')

    current_line = ''
    lines = []
    for i, token in enumerate(tokens):
        is_last = (i == len(tokens) - 1)
        token_len = len(token)
        max_len = 76 if is_last else 75
        if len(current_line) + token_len <= max_len:
            current_line += token
        else:
            lines.append(current_line)
            current_line = token
    if current_line:
        lines.append(current_line)

    result = ''
    for i, line in enumerate(lines):
        result += line
        if i != len(lines) - 1:
            result += '=' + '\r\n'
    return result


def qp_decode(text):
    if not isinstance(text, str):
        raise ValueError("Text must be a string")

    s = text.replace('=\r\n', '')
    bytes_list = []
    i = 0
    while i < len(s):
        if s[i] == '=':
            if i + 2 >= len(s):
                raise ValueError("Incomplete = sequence")
            hex_str = s[i+1:i+3]
            if not all(c in '0123456789abcdefABCDEF' for c in hex_str):
                raise ValueError("Invalid hex digits")
            byte_val = int(hex_str, 16)
            bytes_list.append(byte_val)
            i += 3
        else:
            c = s[i]
            if ord(c) < 32 or ord(c) > 126:
                raise ValueError("Non-printable ASCII character")
            if c == '=':
                raise ValueError("Invalid = not followed by two hex digits")
            bytes_list.append(ord(c))
            i += 1
    return bytes(bytes_list)

import re

def parse_params(value):
    if not isinstance(value, str):
        raise TypeError("Value must be a string")

    # Split into mediatype and parameters
    parts = value.split(';', 1)
    mediatype_part = parts[0].strip()
    params_part = parts[1].strip() if len(parts) > 1 else ''

    # Validate mediatype
    mediatype_re = re.compile(r'^[a-zA-Z0-9!#$%&\'*+-.^_`|~]+/[a-zA-Z0-9!#$%&\'*+-.^_`|~]+$')
    if not mediatype_re.match(mediatype_part):
        raise ValueError("Invalid mediatype")

    mediatype = mediatype_part.lower()
    params = {}

    # Process parameters
    param_strings = params_part.split(';') if params_part else []
    for param_str in param_strings:
        param_str = param_str.strip()
        if not param_str:
            continue

        if '=' not in param_str:
            raise ValueError("Parameter missing '='")

        name, value = param_str.split('=', 1)
        name = name.strip()
        value = value.strip()

        # Validate name
        name_re = re.compile(r'^[a-zA-Z0-9!#$%&\'*+-.^_`|~]+$')
        if not name_re.match(name):
            raise ValueError("Invalid parameter name")

        lower_name = name.lower()
        if lower_name in params:
            raise ValueError("Duplicate parameter name")

        # Process value
        if value.startswith('"') and value.endswith('"'):
            s = value[1:-1]
            processed_value = []
            escaped = False
            for c in s:
                if escaped:
                    if c == '"':
                        processed_value.append('"')
                    elif c == '\\':
                        processed_value.append('\\')
                    else:
                        processed_value.append(c)
                    escaped = False
                else:
                    if c == '\\':
                        escaped = True
                    else:
                        processed_value.append(c)
            if escaped:
                raise ValueError("Quoted string ends with a backslash")
            for char in processed_value:
                if ord(char) < 32 or ord(char) > 126:
                    raise ValueError("Control character in value")
            processed_value = ''.join(processed_value)
        else:
            token_re = re.compile(r'^[a-zA-Z0-9!#$%&\'*+-.^_`|~]+$')
            if not token_re.match(value):
                raise ValueError("Invalid token value in parameter")
            processed_value = value

        params[lower_name] = processed_value

    return (mediatype, params)

def format_params(mediatype, params):
    if not isinstance(mediatype, str):
        raise TypeError("Mediatype must be a string")
    mediatype_re = re.compile(r'^[a-zA-Z0-9!#$%&\'*+-.^_`|~]+/[a-zA-Z0-9!#$%&\'*+-.^_`|~]+$')
    if not mediatype_re.match(mediatype):
        raise ValueError("Invalid mediatype")

    if not isinstance(params, dict):
        raise TypeError("Params must be a dictionary")
    for name, value in params.items():
        if not isinstance(name, str):
            raise TypeError("Parameter names must be strings")
        name_re = re.compile(r'^[a-zA-Z0-9!#$%&\'*+-.^_`|~]+$')
        if not name_re.match(name):
            raise ValueError(f"Invalid parameter name: {name}")
        if not isinstance(value, str):
            raise TypeError("Parameter values must be strings")
        for c in value:
            if ord(c) < 32 or ord(c) > 126:
                raise ValueError(f"Invalid character in value: {c!r}")

    lower_names = [name.lower() for name in params.keys()]
    if len(lower_names) != len(set(lower_names)):
        raise ValueError("Duplicate parameter names (case-insensitive)")

    sorted_params = sorted(params.items(), key=lambda x: x[0].lower())
    param_strings = []

    for name, value in sorted_params:
        lower_name = name.lower()
        if value == '':
            quoted_value = f'"{value}"'
            param_strings.append(f"{lower_name}={quoted_value}")
        else:
            token_re = re.compile(r'^[a-zA-Z0-9!#$%&\'*+-.^_`|~]+$')
            if token_re.match(value):
                param_strings.append(f"{lower_name}={value}")
            else:
                escaped = []
                for c in value:
                    if c == '"':
                        escaped.append('\\"')
                    elif c == '\\':
                        escaped.append('\\\\')
