            raise ValueError(f"Invalid number: {number_str}")
        for c in components:
            if not c.isdigit():
                raise ValueError(f"Invalid number component: {c}")
            if len(c) > 1 and c[0] == '0':
                raise ValueError(f"Leading zero in number: {number_str}")
        current = list(map(int, components))
        if len(current) > 6:
            raise ValueError(f"Number has more than 6 components: {number_str}")
        if prev_num is None:
            if current != [1]:
                raise ValueError(f"First number must be 1: {number_str}")
        else:
            if len(current) == len(prev_num) + 1:
                if current[:-1] != prev_num or current[-1] != 1:
                    raise ValueError(f"Invalid number sequence: {number_str}")
            else:
                max_k = 0
                for k in range(min(len(current), len(prev_num)) + 1):
                    if current[:k] == prev_num[:k]:
                        max_k = k
                    else:
                        break
                if max_k > len(prev_num):
                    raise ValueError(f"Invalid number sequence: {number_str}")
                if len(current) != max_k + 1:
                    raise ValueError(f"Invalid number sequence: {number_str}")
                if max_k < len(prev_num) and current[max_k] != prev_num[max_k] + 1:
                    raise ValueError(f"Invalid number sequence: {number_str}")
        result.append('#' * len(current) + ' ' + title)
        prev_num = current.copy()
    return result

