def aliquot_chain(n, limit):
    if type(n) is not int or type(limit) is not int:
        raise ValueError
    if n < 1 or n > 10**6 or limit < 1 or limit > 1000:
        raise ValueError

    def sum_proper_divisors(m):
        if m == 1:
            return 0
        total = 1
        sqrt_m = int(math.sqrt(m))
        for i in range(2, sqrt_m + 1):
            if m % i == 0:
                other = m // i
                if i == other:
                    total += i
                else:
                    total += i + other
        return total

    terms = [n]
    for _ in range(limit):
        last = terms[-1]
        t = sum_proper_divisors(last)
        if t == 0:
            terms.append(t)
            kind = "terminates"
            break
        if t in terms:
            i = terms.index(t)
            L = len(terms) - i
            if i == 0:
                if L == 1:
                    kind = "perfect"
                elif L == 2:
                    kind = "amicable"
                else:
                    kind = "sociable"
            else:
                if L == 1:
                    kind = "aspiring"
                else:
                    kind = "cyclic"
            break
        if t > 10**9:
            terms.append(t)
            kind = "unknown"
            break
        terms.append(t)
    else:
        kind = "unknown"
    return (kind, terms)

import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    w = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += w
        w = 6 - w
    return True

def factor(n):
    factors = {}
    while n % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        n = n // 2
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n = n // i
        i += 2
    if n > 1:
        factors[n] = 1
    return factors

def euler_phi(n):
    if n == 0:
        return 0
    factors = factor(n)
    result = n
    for p in factors:
        result = result // p * (p - 1)
    return result

def is_valid_n(n):
    if n in (2, 4):
        return True
    if n % 2 == 0:
        m = n // 2
        if m % 2 == 0:
            return False
        m_factors = factor(m)
        if len(m_factors) != 1:
            return False
        p = next(iter(m_factors))
        return is_prime(p)
    else:
        n_factors = factor(n)
        if len(n_factors) != 1:
            return False
        p = next(iter(n_factors))
        return is_prime(p)

def smallest_primitive_root(n):
    if not isinstance(n, int):
        raise ValueError
    if n < 2 or n > 10**10:
        raise ValueError
    if not is_valid_n(n):
        return None
    if n == 2:
        return 1
    phi_n = euler_phi(n)
    if phi_n == 0:
        return None
    factors_phi = factor(phi_n)
    qs = list(factors_phi.keys())
    for g in range(2, n):
        if math.gcd(g, n) != 1:
            continue
        is_primitive = True
        for q in qs:
            exponent = phi_n // q
            if pow(g, exponent, n) == 1:
                is_primitive = False
                break
        if is_primitive:
            return g
    return None

def count_primitive_roots(n):
    if not isinstance(n, int):
        raise ValueError
    if n < 2 or n > 10**10:
        raise ValueError
    if not is_valid_n(n):
        return 0
    phi_n = euler_phi(n)
    return euler_phi(phi_n)

def factorize(b):
    factors = {}
    while b % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        b = b // 2
    i = 3
    while i * i <= b:
        while b % i == 0:
            factors[i] = factors.get(i, 0) + 1
            b = b // i
        i += 2
    if b > 2:
        factors[b] = 1
    return factors

def legendre(m, p):
    count = 0
    while m > 0:
        m = m // p
        count += m
    return count

def trailing_zeros(n, b):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("n must be an integer")
    if n < 0 or n > 10**18:
        raise ValueError("n is out of range")
    if not isinstance(b, int) or isinstance(b, bool):
        raise ValueError("b must be an integer")
    if b < 2 or b > 10**6:
        raise ValueError("b is out of range")

    factors = factorize(b)
    min_z = float('inf')
    for p in factors:
        e_p = factors[p]
        v = legendre(n, p)
        z = v // e_p
        if z < min_z:
            min_z = z
        if min_z == 0:
            break
    return min_z

def binomial_zeros(n, k, b):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("n must be an integer")
    if n < 0 or n > 10**18:
        raise ValueError("n is out of range")
    if not isinstance(k, int) or isinstance(k, bool):
        raise ValueError("k must be an integer")
    if k < 0 or k > n:
        raise ValueError("k is out of range")
    if not isinstance(b, int) or isinstance(b, bool):
        raise ValueError("b must be an integer")
    if b < 2 or b > 10**6:
        raise ValueError("b is out of range")

    factors = factorize(b)
    min_z = float('inf')
    for p in factors:
        e_p = factors[p]
        v_n = legendre(n, p)
        v_k = legendre(k, p)
        v_nk = legendre(n - k, p)
        v_total = v_n - v_k - v_nk
        z = v_total // e_p
        if z < min_z:
            min_z = z
        if min_z == 0:
            break
    return min_z if min_z != float('inf') else 0

def lucky_numbers(limit):
    if type(limit) is not int:
        raise ValueError
    if limit < 0 or limit > 10**5:
        raise ValueError

    if limit == 0:
        return []

    L = list(range(1, limit + 1, 2))
    if not L:
        return []

    index = 1  # Start with the second element (3)
    while index < len(L):
        step = L[index]
        if step > len(L):
            break
        # Create a new list excluding every step-th element
        new_L = []
        for i, num in enumerate(L, 1):
            if i % step != 0:
                new_L.append(num)
        L = new_L
        index += 1

    return L

def nth_lucky(k):
    if type(k) is not int:
