    return lucky_list[k - 1]

def factorize(x):
    factors = {}
    while x % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        x = x // 2
    i = 3
    while i * i <= x:
        while x % i == 0:
            factors[i] = factors.get(i, 0) + 1
            x = x // i
        i += 2
    if x > 1:
        factors[x] = 1
    return factors

def get_divisors(factors):
    divisors = [1]
    for p in factors:
        exponents = [p**e for e in range(1, factors[p] + 1)]
        temp = []
        for d in divisors:
            for exp in exponents:
                temp.append(d * exp)
        divisors += temp
    divisors = list(set(divisors))  # Remove duplicates
    divisors.sort()
    return divisors

def consecutive_sums(n):
    if type(n) is not int or n < 1 or n > 10**12:
        raise ValueError
    two_n = 2 * n
    factors = factorize(two_n)
    divisors = get_divisors(factors)
    runs = []
    for k in divisors:
        if k < 2:
            continue
        m = two_n // k
        temp = m - k + 1
        if temp > 0 and temp % 2 == 0:
            a = temp // 2
            b = a + k - 1
            runs.append((a, b))
    runs.sort()
    return runs

def count_consecutive_sums(n):
    if type(n) is not int or n < 1 or n > 10**12:
        raise ValueError
    factors = factorize(n)
    num_odd_divisors = 1
    for p in factors:
        if p % 2 != 0:
            num_odd_divisors *= (factors[p] + 1)
    return max(0, num_odd_divisors - 1)

from collections import deque

def lca_answers(parent, queries):
    # Validate parent list
    n = len(parent)
    if n == 0:
        raise ValueError
    for v in parent:
        if type(v) is bool:
            raise ValueError
    root_count = 0
    for v in parent:
        if v == -1:
            root_count += 1
    if root_count != 1:
        raise ValueError
    for v in parent:
        if v != -1 and (v < 0 or v >= n):
            raise ValueError

    # Build children list and find root
    children = [[] for _ in range(n)]
    root = -1
    for i in range(n):
        p = parent[i]
        if p == -1:
            if root != -1:
                raise ValueError
            root = i
        else:
            children[p].append(i)

    # Compute depths using BFS
    depth = [0] * n
    visited = [False] * n
    q = deque()
    q.append(root)
    visited[root] = True
    while q:
        u = q.popleft()
        for v in children[u]:
            if not visited[v]:
                depth[v] = depth[u] + 1
                visited[v] = True
                q.append(v)
    if any(not visited[i] for i in range(n)):
        raise ValueError

    # Build binary lifting table
    log_max = 0
    while (1 << log_max) <= n:
        log_max += 1
    log_max -= 1
    up = [[-1] * n for _ in range(log_max + 1)]
    for i in range(n):
        up[0][i] = parent[i]
    for k in range(1, log_max + 1):
        for i in range(n):
            if up[k-1][i] != -1:
                up[k][i] = up[k-1][up[k-1][i]]
            else:
                up[k][i] = -1

    # Validate queries
    if not isinstance(queries, list):
        raise ValueError
    for q in queries:
        if not isinstance(q, (list, tuple)) or len(q) != 2:
            raise ValueError
        u, v = q
        if not isinstance(u, int) or not isinstance(v, int):
            raise ValueError
        if type(u) is bool or type(v) is bool:
            raise ValueError
        if u < 0 or u >= n or v < 0 or v >= n:
            raise ValueError

    # Process each query
    result = []
    for q in queries:
        u, v = q
        a, b = u, v
        if depth[a] < depth[b]:
            a, b = b, a

        # Bring a up to the depth of b
        for k in range(log_max, -1, -1):
            if depth[a] - (1 << k) >= depth[b]:
                a = up[k][a]

        if a == b:
            lca_node = a
        else:
            for k in range(log_max, -1, -1):
                if up[k][a] != -1 and up[k][a] != up[k][b]:
                    a = up[k][a]
                    b = up[k][b]
            lca_node = up[0][a]

        distance = depth[u] + depth[v] - 2 * depth[lca_node]
        result.append((lca_node, distance))

    return result

