def lca_answers(parent, queries):
    # Validate parent
    n = len(parent)
    if n == 0:
        if not queries:
            return []
        else:
            raise ValueError

    # Check each element is an integer (not bool)
    for e in parent:
        if not isinstance(e, int) or isinstance(e, bool):
            raise ValueError

    # Check for exactly one root
    roots = [v for v in range(n) if parent[v] == -1]
    if len(roots) != 1:
        raise ValueError
    root = roots[0]

    # Check each parent is a valid index and not self
    for v in range(n):
        p = parent[v]
        if p == -1:
            if v != root:
                raise ValueError
        else:
            if p == v:
                raise ValueError
            if not (0 <= p < n):
                raise ValueError

    # Validate queries
    if not isinstance(queries, list):
        raise ValueError
    for q in queries:
        if not isinstance(q, (list, tuple)) or len(q) != 2:
            raise ValueError
        u, v = q
        if not isinstance(u, int) or not isinstance(v, int):
            raise ValueError
        if not (0 <= u < n and 0 <= v < n):
            raise ValueError

    # Build children list
    children = [[] for _ in range(n)]
    for v in range(n):
        p = parent[v]
        if p != -1:
            children[p].append(v)

    # Compute depth using BFS and check reachability
    depth = [0] * n
    expected_parent = [-1] * n
    queue = deque([root])
    expected_parent[root] = -1

    while queue:
        u = queue.popleft()
        for v in children[u]:
            if expected_parent[v] != -1:
                # This indicates a cycle or multiple parents
                raise ValueError
            expected_parent[v] = u
            depth[v] = depth[u] + 1
            queue.append(v)

    # Check all nodes are reachable and have correct parent
    for v in range(n):
        if v == root:
            if parent[v] != -1:
                raise ValueError
        else:
            if parent[v] != expected_parent[v]:
                raise ValueError
            if depth[v] == 0:
                raise ValueError

    # Build binary lifting table
    LOG = 15  # Sufficient for n up to 2^15
    up = [[-1] * n for _ in range(LOG)]
    for v in range(n):
        up[0][v] = parent[v] if parent[v] != -1 else -1

    for k in range(1, LOG):
        for v in range(n):
            if up[k-1][v] != -1:
                up[k][v] = up[k-1][up[k-1][v]]
            else:
                up[k][v] = -1

    # Process each query
    result = []
    for q in queries:
        u, v = q
        # Bring both nodes to the same depth
        if depth[u] < depth[v]:
            u, v = v, u
        # Lift u up to the depth of v
        for k in range(LOG-1, -1, -1):
            if depth[u] - (1 << k) >= depth[v]:
                u = up[k][u]
        if u == v:
            lca_node = u
        else:
            # Now find the LCA
            for k in range(LOG-1, -1, -1):
                if up[k][u] != -1 and up[k][u] != up[k][v]:
                    u = up[k][u]
                    v = up[k][v]
            lca_node = up[0][u]

        # Calculate distance
        distance = depth[u] + depth[v] - 2 * depth[lca_node]
        result.append((lca_node, distance))

    return result

