def maze_steps(grid):
    # Validate input
    if not isinstance(grid, list) or not all(isinstance(row, str) for row in grid):
        raise ValueError
    rows = len(grid)
    if rows < 1 or rows > 30:
        raise ValueError
    if rows == 0:
        raise ValueError
    cols = len(grid[0])
    if cols < 1 or cols > 30:
        raise ValueError
    for row in grid:
        if len(row) != cols:
            raise ValueError
        for c in row:
            if c not in {'#', '.', 'S', 'E', 'a', 'b', 'c', 'd', 'A', 'B', 'C', 'D'}:
                raise ValueError
    # Find start and exit positions
    start = None
    exit_pos = None
    count_S = 0
    count_E = 0
    for i in range(rows):
        for j in range(cols):
            c = grid[i][j]
            if c == 'S':
                start = (i, j)
                count_S += 1
            elif c == 'E':
                exit_pos = (i, j)
                count_E += 1
    if count_S != 1 or count_E != 1:
        raise ValueError

    # BFS initialization
    queue = deque()
    visited = set()
    start_row, start_col = start
    exit_row, exit_col = exit_pos
    initial_keys = 0
    queue.append((start_row, start_col, initial_keys, 0))
    visited.add((start_row, start_col, initial_keys))

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        row, col, keys, steps = queue.popleft()

        # Check if current position is the exit
        if row == exit_row and col == exit_col:
            return steps

        for dr, dc in directions:
            new_row = row + dr
            new_col = col + dc
            if 0 <= new_row < rows and 0 <= new_col < cols:
                cell = grid[new_row][new_col]
                if cell == '#':
                    continue
                # Check if it's a door
                if 'A' <= cell <= 'D':
                    key_char = cell.lower()
                    key_bit = ord(key_char) - ord('a')
                    if not (keys & (1 << key_bit)):
                        continue
                # Update keys if it's a key
                new_keys = keys
                if 'a' <= cell <= 'd':
                    new_keys = keys | (1 << (ord(cell) - ord('a')))
                # Check if this move leads to exit
                if new_row == exit_row and new_col == exit_col:
                    return steps + 1
                # Check if this state has been visited
                state = (new_row, new_col, new_keys)
                if state not in visited:
                    visited.add(state)
                    queue.append((new_row, new_col, new_keys, steps + 1))

    # If exit is unreachable
    return -1

