    variables = set()
    equalities = []
    disequalities = []
    for s in constraints:
        if not isinstance(s, str):
            raise ValueError
        if len(s) < 4:
            raise ValueError
        op_pos = -1
        op = None
        for i in range(len(s) - 1):
            substr = s[i:i+2]
            if substr == '==' or substr == '!=':
                op_pos = i
                op = substr
                break
        if op is None:
            raise ValueError("Invalid constraint: no operator")
        x = s[:op_pos]
        y = s[op_pos+2:]
        if not is_valid_variable(x) or not is_valid_variable(y):
            raise ValueError("Invalid variable name")
