            return False
        if op == '==':
            equalities.append((x, y))
        else:
            disequalities.append((x, y))
        variables.add(x)
        variables.add(y)
    if not variables:
        return True
    parent = {var: var for var in variables}
    rank = {var: 0 for var in variables}
    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u
    def union(u, v):
        u_root = find(u)
        v_root = find(v)
        if u_root == v_root:
            return
        if rank[u_root] < rank[v_root]:
            parent[u_root] = v_root
        else:
            parent[v_root] = u_root
            if rank[u_root] == rank[v_root]:
                rank[u_root] += 1
    for x, y in equalities:
