def rho_shapes(f):
    if not isinstance(f, list):
        raise ValueError
    n = len(f)
    if n == 0:
        raise ValueError
    for v in f:
        if not isinstance(v, int):
            raise ValueError
        if v < 0 or v >= n:
            raise ValueError

    result = [ (0, 0) for _ in range(n) ]
    visited = [0] * n  # 0: unvisited, 1: visiting, 2: visited

    for v in range(n):
        if visited[v] != 0:
            continue
        path = []
        current = v
        while True:
            if visited[current] == 1:
                # Found a cycle in the current path
                idx = path.index(current)
                cycle = path[idx:]
                cycle_length = len(cycle)
                # Mark cycle nodes as visited and set their result
                for node in cycle:
                    visited[node] = 2
                    result[node] = (0, cycle_length)
                # Process the nodes before the cycle
                for i in range(idx - 1, -1, -1):
                    node = path[i]
                    result[node] = (idx - i, cycle_length)
                break
            if visited[current] == 2:
                # The current path leads into a previously processed node
