def interleave_count(a, b, c):
    if not isinstance(a, str) or not isinstance(b, str) or not isinstance(c, str):
        raise ValueError
    if len(a) > 300 or len(b) > 300:
        raise ValueError
    if len(c) != len(a) + len(b):
        return 0
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = 1
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 and j == 0:
                continue
            current_char = c[i + j - 1]
            if i > 0 and a[i - 1] == current_char:
                dp[i][j] += dp[i - 1][j]
            if j > 0 and b[j - 1] == current_char:
                dp[i][j] += dp[i][j - 1]
    return dp[m][n]

def interleave_labels(a, b, c):
    if not isinstance(a, str) or not isinstance(b, str) or not isinstance(c, str):
        raise ValueError
    if len(a) > 300 or len(b) > 300:
        raise ValueError
    if len(c) != len(a) + len(b):
        return None
    m, n = len(a), len(b)
    reachable = [[False] * (n + 1) for _ in range(m + 1)]
    reachable[m][n] = True
    for i in range(m, -1, -1):
        for j in range(n, -1, -1):
            if i == m and j == n:
                continue
            current_pos = i + j
            if current_pos >= len(c):
                reachable[i][j] = False
                continue
            current_char = c[current_pos]
            if i < m and a[i] == current_char:
                if reachable[i + 1][j]:
                    reachable[i][j] = True
                    continue
            if j < n and b[j] == current_char:
                if reachable[i][j + 1]:
                    reachable[i][j] = True
                    continue
    if not reachable[0][0]:
        return None
    labels = []
    i, j = 0, 0
    for _ in range(len(c)):
        current_char = c[i + j]
        if i < m and a[i] == current_char and reachable[i + 1][j]:
            labels.append('A')
            i += 1
        elif j < n and b[j] == current_char and reachable[i][j + 1]:
            labels.append('B')
            j += 1
        else:
            return None
    return ''.join(labels)

