        raise ValueError
    if type(steps) is not int:
        raise ValueError
    if steps < 0 or steps > 10**5:
        raise ValueError

    k = len(rule)
    directions = ['N', 'E', 'S', 'W']
    deltas = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    x, y = 0, 0
    dir_idx = 0  # Start facing North
    grid = {}
    colored = 0

    for _ in range(steps):
        current_color = grid.get((x, y), 0)
        turn = rule[current_color]
        if turn == 'L':
            dir_idx = (dir_idx - 1) % 4
        else:
            dir_idx = (dir_idx + 1) % 4

        new_color = (current_color + 1) % k
        if new_color == 0:
            if (x, y) in grid:
                del grid[(x, y)]
                colored -= 1
        else:
            if (x, y) in grid:
                if grid[(x, y)] != new_color:
                    grid[(x, y)] = new_color
            else:
                grid[(x, y)] = new_color
                colored += 1

        dx, dy = deltas[dir_idx]
        x += dx
        y += dy

    heading = directions[dir_idx]
    return (x, y, heading, colored)

