import collections

def topple(grid):
    # Validate input
    if not isinstance(grid, list) or len(grid) == 0:
        raise ValueError
    row_length = len(grid[0])
    for row in grid:
        if not isinstance(row, list) or len(row) != row_length:
            raise ValueError
        for cell in row:
            if not isinstance(cell, int) or isinstance(cell, bool) or cell < 0 or cell > 10**4:
                raise ValueError

    # Create a deep copy of the grid
    stable = [row.copy() for row in grid]
    rows = len(stable)
    cols = len(stable[0]) if rows > 0 else 0

    # Initialize the queue with all unstable cells
    q = collections.deque()
    for i in range(rows):
        for j in range(cols):
            if stable[i][j] >= 4:
                q.append((i, j))

    count = 0
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while q:
        i, j = q.popleft()
        grains = stable[i][j]
        if grains < 4:
            continue
        times = grains // 4
        count += times
        stable[i][j] -= 4 * times

        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < rows and 0 <= nj < cols:
                stable[ni][nj] += times
                if stable[ni][nj] >= 4:
                    q.append((ni, nj))

    return (stable, count)

