def realize_gains(trades, method):
    if method not in ('fifo', 'lifo'):
        raise ValueError

    lots = []
    total_gain = 0

    for trade in trades:
        if len(trade) != 3:
            raise ValueError
        kind, qty, price = trade

        if kind not in ('buy', 'sell'):
            raise ValueError

        if type(qty) is not int:
            raise ValueError
        if qty < 1:
            raise ValueError

        if type(price) is not int:
            raise ValueError
        if price < 0:
            raise ValueError

        if kind == 'buy':
            lots.append([qty, price])
        else:
            required = qty
            current_gain = 0

            if method == 'fifo':
                for i in range(len(lots)):
                    if required <= 0:
                        break
                    lot = lots[i]
                    if lot[0] <= 0:
                        continue
                    take = min(lot[0], required)
                    current_gain += take * (price - lot[1])
                    lot[0] -= take
                    required -= take
            else:
                for i in range(len(lots)-1, -1, -1):
                    if required <= 0:
                        break
                    lot = lots[i]
                    if lot[0] <= 0:
                        continue
                    take = min(lot[0], required)
                    current_gain += take * (price - lot[1])
                    lot[0] -= take
                    required -= take

            if required > 0:
                raise ValueError

            total_gain += current_gain

    lots = [lot for lot in lots if lot[0] > 0]
    lots = [(lot[0], lot[1]) for lot in lots]

    return (total_gain, lots)

