        term_dist = defaultdict(int)
        term_dist[0] = 1
        for _ in range(n):
            new_term = defaultdict(int)
            for current_sum, count in term_dist.items():
                for face in range(1, s + 1):
                    new_sum = current_sum + face
                    new_term[new_sum] += count
            term_dist = new_term
        new_current = defaultdict(int)
        for a_sum, a_count in current_dist.items():
            for b_sum, b_count in term_dist.items():
                total_sum = a_sum + b_sum
                new_current[total_sum] += a_count * b_count
        current_dist = new_current
    final_dist = defaultdict(int)
    for s, cnt in current_dist.items():
        final_sum = s + base
        final_dist[final_sum] += cnt
    return dict(final_dist)

