            if not term.isdigit():
                raise ValueError("Invalid constant")
            if len(term) > 1 and term[0] == '0':
                raise ValueError("Invalid constant")
            constant = int(term)
            if constant < 0 or constant > 1000:
                raise ValueError("Invalid constant")
            constants.append(constant)
    total_dice = sum(N for (N, S) in dice_terms)
    if total_dice > 20:
        raise ValueError("Too many dice")
    return dice_terms, sum(constants)

def build_distribution(dice_terms, total_constant):
    distribution = defaultdict(int)
    distribution[0] = 1
    for (N, S) in dice_terms:
        for _ in range(N):
            temp = defaultdict(int)
            for current_sum, count in distribution.items():
                for face in range(1, S + 1):
                    new_sum = current_sum + face
                    temp[new_sum] += count
            distribution = temp
    new_distribution = defaultdict(int)
    for s, count in distribution.items():
        new_distribution[s + total_constant] += count
    return dict(new_distribution)

def dice_counts(spec):
    dice_terms, total_constant = parse_spec(spec)
    return build_distribution(dice_terms, total_constant)

def chance_at_least(spec, target):
    if type(target) is not int:
        raise ValueError("Target must be an integer")
    dice_terms, total_constant = parse_spec(spec)
    distribution = build_distribution(dice_terms, total_constant)
    sum_counts = 0
    for s, count in distribution.items():
        if s >= target:
            sum_counts += count
    total_outcomes = 1
    for (N, S) in dice_terms:
        total_outcomes *= (S ** N)
    return Fraction(sum_counts, total_outcomes)
